const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const date = '2018-09-15';
  const point1 = ee.Geometry.Point([136.025799, 33.710618]); // Location 1
  const point2 = ee.Geometry.Point([136.367495, 33.884848]); // Location 2

  // 2. Data Acquisition
  const modisCollection = ee.ImageCollection('MODIS/061/MOD09GA')
    .filterDate(date, ee.Date(date).advance(1, 'day'));

  // 3. Processing
  // Check if collection is empty
  const imageCount = modisCollection.size().getInfo();
  if (imageCount === 0) {
    console.log("Evidence: No MODIS Terra images found for the specified date.");
    console.log("C1");
    return;
  }
  const image = modisCollection.first();

  // Turbidity is approximated by reflectance in the red band (Band 1).
  const turbidityBand = 'sur_refl_b01';

  // Function to mask clouds and non-water pixels using the state_1km QA band
  // Bits 0-1: Cloud State (0 = clear)
  // Bit 2: Land/Water (1 = water)
  function maskMODIS(img) {
    const qa = img.select('state_1km');
    const cloudMask = qa.bitwiseAnd(3).eq(0); // Select bit 0-1 == 0 (clear)
    const waterMask = qa.bitwiseAnd(4).eq(4); // Select bit 2 == 1 (water)
    return img.updateMask(cloudMask).updateMask(waterMask);
  }

  const maskedImage = maskMODIS(image);
  const scale = 500; // Native resolution for the band

  // 4. Calculation
  // Function to extract value and pixel count for a point
  function getStats(point, label) {
    const region = point.buffer(scale).bounds(); // Buffer by scale to ensure pixel capture
    const data = maskedImage.select(turbidityBand).reduceRegion({
      reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    });
    return ee.Dictionary(data).get(turbidityBand);
  }

  const stats1 = getStats(point1, 'Location 1').getInfo();
  const stats2 = getStats(point2, 'Location 2').getInfo();

  // 5. Validation & Final Answer
  // Check for C2: No Valid Pixels
  if (!stats1 || stats1.count === 0) {
      console.log(`Evidence: Location 1 (33.71, 136.02) has 0 valid (clear, water) pixels.`);
      console.log("C2");
      return;
  }
  if (!stats2 || stats2.count === 0) {
      console.log(`Evidence: Location 2 (33.88, 136.36) has 0 valid (clear, water) pixels.`);
      console.log("C2");
      return;
  }

  // Check for C3: Calculation Failure
  if (stats1.mean === null || stats2.mean === null) {
      console.log(`Evidence: Calculation failed. Mean value is null for one or both locations.`);
      console.log(`Location 1 Value: ${stats1.mean}`);
      console.log(`Location 2 Value: ${stats2.mean}`);
      console.log("C3");
      return;
  }

  const turbidity1 = stats1.mean;
  const turbidity2 = stats2.mean;

  console.log(`Evidence: Location 1 Turbidity (Red Reflectance): ${turbidity1.toFixed(4)}`);
  console.log(`Evidence: Location 2 Turbidity (Red Reflectance): ${turbidity2.toFixed(4)}`);
  console.log(`Note: Higher reflectance suggests higher turbidity.`);

  if (turbidity1 > turbidity2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred during the analysis.");
    console.error(err);
    console.log("D");
});
